plugins {
    id("gradlebuild.distribution.api-java")
}

description = "Marker class file used to locate the Gradle distribution base directory"

gradleModule {
    // Installation beacon should not be part of the public API
    publicApiStubs = false

    requiredRuntimes {
        client = true
        daemon = true
        worker = true
    }
    computedRuntimes {
        // Auto-generated by `:checkTargetRuntimes --fix`
        client = true
        daemon = true
        worker = true
    }
}

// This lib should not have any dependencies.

errorprone {
    nullawayEnabled = true
}
